// Class (Reference Type)
public class Person {
    public string Name;
    public int Age;
}

Person p1 = new Person { Name = "Alice", Age = 30 };
Person p2 = p1; // Copies reference, both point to same object
p2.Name = "Bob"; // Also changes p1.Name

// Struct (Value Type)
public struct Point {
    public int X;
    public int Y;
}

Point pt1 = new Point { X = 10, Y = 20 };
Point pt2 = pt1; // Copies entire struct
pt2.X = 100; // pt1.X remains 10
